def factorial(n):
    if n == 0:                 # trường hợp cơ sở
        return 1
    return n * factorial(n - 1)   # bước đệ quy

print(factorial(5))            # 120

def merge(a, b):
    out = []
    while a and b:
        out.append(a.pop(0) if a[0] <= b[0] else b.pop(0))
    return out + a + b

def merge_sort(xs):
    if len(xs) <= 1:
        return xs
    m = len(xs) // 2
    return merge(merge_sort(xs[:m]), merge_sort(xs[m:]))

print(merge_sort([5, 2, 9, 1, 7]))

